create table public.households(id uuid primary key default gen_random_uuid(),name text not null default 'My Household',invite_code text not null unique default upper(substr(encode(gen_random_bytes(8),'hex'),1,8)),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.household_members(household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','member')),joined_at timestamptz not null default now(),primary key(household_id,user_id),unique(user_id));
alter table public.households enable row level security;alter table public.household_members enable row level security;
create or replace function public.current_household_id() returns uuid language sql stable security definer set search_path=public as $$select household_id from public.household_members where user_id=auth.uid() limit 1$$;
create or replace function public.create_user_household() returns trigger language plpgsql security definer set search_path=public as $$declare h uuid;begin insert into public.households(name,created_by) values(coalesce(new.raw_user_meta_data->>'full_name','My')||'''s Household',new.id) returning id into h;insert into public.household_members(household_id,user_id,role) values(h,new.id,'owner');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_user_household();
alter table public.floors add column household_id uuid references public.households(id) default public.current_household_id();alter table public.rooms add column household_id uuid references public.households(id) default public.current_household_id();alter table public.tenants add column household_id uuid references public.households(id) default public.current_household_id();alter table public.documents add column household_id uuid references public.households(id) default public.current_household_id();alter table public.bills add column household_id uuid references public.households(id) default public.current_household_id();
update public.floors f set household_id=(select household_id from public.household_members where user_id=f.owner_id);update public.rooms r set household_id=(select household_id from public.household_members where user_id=r.owner_id);update public.tenants t set household_id=(select household_id from public.household_members where user_id=t.owner_id);update public.documents d set household_id=(select household_id from public.household_members where user_id=d.owner_id);update public.bills b set household_id=(select household_id from public.household_members where user_id=b.owner_id);
alter table public.floors alter column household_id set not null;alter table public.rooms alter column household_id set not null;alter table public.tenants alter column household_id set not null;alter table public.documents alter column household_id set not null;alter table public.bills alter column household_id set not null;
drop policy if exists "Owner controls own floors" on public.floors;drop policy if exists "Owner controls own rooms" on public.rooms;drop policy if exists "Owner controls own tenants" on public.tenants;drop policy if exists "Owner controls own documents" on public.documents;drop policy if exists "Owner controls own bills" on public.bills;
do $$declare t text;begin foreach t in array array['floors','rooms','tenants','documents','bills'] loop execute format('create policy "Household members control %1$s" on public.%1$I for all to authenticated using (household_id=public.current_household_id()) with check (household_id=public.current_household_id())',t);end loop;end$$;
create policy "Members view household" on public.households for select to authenticated using(id=public.current_household_id());create policy "Members view memberships" on public.household_members for select to authenticated using(household_id=public.current_household_id());
create or replace function public.my_household() returns table(household_id uuid,household_name text,invite_code text,member_count bigint) language sql stable security definer set search_path=public as $$select h.id,h.name,h.invite_code,count(m.user_id) from public.households h join public.household_members m on m.household_id=h.id where h.id=public.current_household_id() group by h.id$$;
create or replace function public.join_household(share_code text) returns void language plpgsql security definer set search_path=public as $$declare target_id uuid;current_id uuid;member_total int;begin select id into target_id from public.households where invite_code=upper(trim(share_code));if target_id is null then raise exception 'Invalid household code';end if;select count(*) into member_total from public.household_members where household_id=target_id;if member_total>=4 then raise exception 'This household already has 4 members';end if;select household_id into current_id from public.household_members where user_id=auth.uid();if exists(select 1 from public.floors where household_id=current_id) then raise exception 'This account already owns property data and cannot switch households';end if;delete from public.household_members where user_id=auth.uid();insert into public.household_members(household_id,user_id,role) values(target_id,auth.uid(),'member');delete from public.households where id=current_id and not exists(select 1 from public.household_members where household_id=current_id);end$$;
drop policy if exists "Owner uploads private files" on storage.objects;drop policy if exists "Owner reads private files" on storage.objects;drop policy if exists "Owner updates private files" on storage.objects;drop policy if exists "Owner deletes private files" on storage.objects;
create policy "Members upload household files" on storage.objects for insert to authenticated with check(bucket_id='tenant-private' and (storage.foldername(name))[1]=public.current_household_id()::text);create policy "Members read household files" on storage.objects for select to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=public.current_household_id()::text);create policy "Members update household files" on storage.objects for update to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=public.current_household_id()::text);create policy "Members delete household files" on storage.objects for delete to authenticated using(bucket_id='tenant-private' and (storage.foldername(name))[1]=public.current_household_id()::text);
grant execute on function public.my_household() to authenticated;grant execute on function public.join_household(text) to authenticated;
revoke execute on function public.my_household() from public;revoke execute on function public.join_household(text) from public;revoke execute on function public.current_household_id() from public;grant execute on function public.current_household_id() to authenticated;
